import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Color Change","description":"","frontmatter":{"title":"Color Change","phenomenon":"color-change"},"headers":[],"relativePath":"classification/optical-phenomena/color-change.md","filePath":"classification/optical-phenomena/color-change.md","lastUpdated":1790876393000}'),i={name:"classification/optical-phenomena/color-change.md"};function o(l,e,s,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="color-change" tabindex="-1">Color Change <a class="header-anchor" href="#color-change" aria-label="Permalink to &quot;Color Change&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A few gems exhibit distinctly different hues under daylight (rich in blue-green) versus incandescent light (rich in red- yellow). The classic case is alexandrite, green in daylight and red in candlelight. Other Cr³⁺ / V³⁺-bearing species (sapphire, pyrope, certain spinels) can show similar effects. Mechanism: dual absorption bands of Cr³⁺ centered in the yellow and blue-green ranges.</p><h2 id="mechanism" tabindex="-1">Mechanism <a class="header-anchor" href="#mechanism" aria-label="Permalink to &quot;Mechanism&quot;">​</a></h2><p>Cr³⁺ exhibits two principal absorption bands: one in the yellow (~580 nm) and one in the blue (~425 nm). Under daylight (blue- green rich), yellow light is transmitted → green appearance. Under incandescent light (red-yellow rich), yellow is absorbed and blue transmission dominates, combining with the red ambient to yield red/purple. The greater the green-vs-red contrast, the higher the alexandrite rating.</p><h2 id="example-gemstones" tabindex="-1">Example Gemstones <a class="header-anchor" href="#example-gemstones" aria-label="Permalink to &quot;Example Gemstones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Daylight</th><th>Incandescent</th></tr></thead><tbody><tr><td>Alexandrite / 亚历山大石</td><td>green / teal</td><td>red / raspberry</td></tr><tr><td>Color-change Sapphire / 变色蓝宝</td><td>blue</td><td>purple</td></tr><tr><td>Color-change Garnet / 变色石榴石</td><td>blue-green</td><td>red-purple</td></tr><tr><td>Color-change Spinel / 变色尖晶石</td><td>blue</td><td>violet</td></tr><tr><td>Color-change Fluorite / 变色萤石</td><td>blue</td><td>purple</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA: Guide to Phenomenal Gems</a><span>Observation methods and gemological context for optical phenomena</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA: Optical Effects of Phenomenal Cabochons</a><span>Cabochon cuts, lighting, viewing angle, and optical appearance</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">optical phenomena overview</a>.</em></p>',9)])])}const g=a(i,[["render",o]]);export{m as __pageData,g as default};
